create extension if not exists pgcrypto;
create schema if not exists auth;
create table auth.users(id uuid primary key, email text);
create or replace function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create or replace function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims', true),''),'{}')::jsonb $$;
create table public.den_admin_log(id bigserial primary key, at timestamptz default now() not null, admin text, action text, target text, detail jsonb);
create table public.den_allow(email text primary key, is_admin boolean default false not null);
create table public.den_waitlist(id uuid default gen_random_uuid() primary key, email text not null, created_at timestamptz default now() not null);
create table public.os_bag(uid uuid not null, item_id text not null, qty integer not null check (qty > 0), primary key(uid,item_id));
create table public.os_config(key text primary key, value jsonb not null, updated_at timestamptz default now() not null);
create table public.os_crew(id uuid default gen_random_uuid() primary key, name text not null, code text unique not null, owner uuid, motto text, vault jsonb default '{}' not null, goal_need int default 50000 not null, goal_have int default 0 not null, cup int default 0 not null, created_at timestamptz default now() not null);
create table public.os_crew_member(crew_id uuid not null, uid uuid primary key, role text default 'member' not null);
create table public.os_chat(id bigint generated by default as identity primary key, crew_id uuid not null, uid uuid, body text not null, created_at timestamptz default now() not null);
create table public.os_delve(uid uuid primary key, party text[] not null, floor int not null, minutes int not null, started_at timestamptz default now() not null, ends_at timestamptz not null, choice text, seed bigint);
create table public.os_event(id bigint generated by default as identity primary key, uid uuid, kind text not null, qty int default 1 not null, ref text, created_at timestamptz default now() not null);
create table public.os_feed(id bigserial primary key, at timestamptz default now() not null, msg text not null, tag text default 'news' not null);
create table public.os_hero(uid uuid not null, hero_id text not null, level int default 1 not null, dupes int default 0 not null, got_at timestamptz default now() not null, primary key(uid,hero_id));
create table public.os_hero_def(id text primary key, name text not null, title text not null, rarity text not null, era text not null, found boolean default false not null, items text[] default '{}' not null);
create table public.os_hustle_log(id bigint generated by default as identity primary key, uid uuid not null, result text not null, detail text not null, gold int default 0 not null, created_at timestamptz default now() not null);
create table public.os_infirmary(uid uuid not null references auth.users(id) on delete cascade, hero_id text not null, until timestamptz not null, reason text, primary key(uid,hero_id));
create table public.os_item_def(id text primary key, name text not null, rarity text not null, slot text not null, hero_id text, in_pool boolean default false not null);
create table public.os_listing(id bigint generated by default as identity primary key, seller uuid, kind text default 'item' not null, item_id text, hero_id text, hero_level int, qty int default 1 not null, price int not null, created_at timestamptz default now() not null);
create table public.os_player(uid uuid primary key, name text not null, gold int default 0 not null, deepest int default 1 not null, party text[] default '{}' not null, rules jsonb default '{"heal": 40, "loot": "balanced", "retreat": 25}' not null, created_at timestamptz default now() not null, sigils int default 1 not null, vigor int default 100 not null, daring int default 10 not null, life int default 100 not null, life_max int default 100 not null, city text default 'aldermere' not null, travel_to text, travel_until timestamptz, stocks_until timestamptz, banned boolean default false not null, ban_reason text, hustle_xp int default 0 not null, seen_at timestamptz default now() not null, last_tick timestamptz default now() not null, vigor_at timestamptz default now() not null, daring_at timestamptz default now() not null, skill jsonb default '{}' not null, pending jsonb);
create table public.os_trade(id bigint generated by default as identity primary key, item_id text, price int not null, qty int not null, created_at timestamptz default now() not null);

